def absorb(args):
    result = []
    for expr in args:
        absorbed = False
        for i in range(len(expr) - 1):
            if expr[i] == expr[i + 1]:
                result.append(expr[i] * 2)
                absorbed = True
                break
        if not absorbed:
            result.append(expr)
    return result

class HookRegistry:
    def __init__(self):
        self._hooks = {}

    def register_hook(self, hook, handler):
        if hook not in self._hooks:
            self._hooks[hook] = []
        self._hooks[hook].append(handler)

    def get_hooks(self, hook):
        return self._hooks.get(hook, [])

    def on(self, hook):
        def decorator(handler):
            self.register_hook(hook, handler)
            return handler
        return decorator

