import re

def get_pattern(pattern, strip=True):
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    elif isinstance(pattern, re.Pattern):
        return pattern
    else:
        raise ValueError("Input must be a string or an existing regex pattern object")

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        full_command = [command] + args
        if verbose:
            print(f"Running: {' '.join(full_command)}")

        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = None

        result = subprocess.run(
            full_command,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr,
            env=env
        )

        if verbose:
            print(f"Command finished with return code: {result.returncode}")

        return result.stdout, result.returncode

import rdflib
from typing import Set, Optional

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.term.Node]] = None) -> Set[rdflib.term.Node]:
    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        roots.add(o)
        roots.update(find_roots(graph, prop, roots))

    return roots

